update public.questions set source_quote = "«كل سلامى من الناس عليه صدقة، كل يوم تطلع فيه الشمس: تعدل بين اثنين صدقة، وتعين الرجل في دابته فتحمله عليها أو ترفع له عليها متاعه صدقة، والكلمة الطيبة صدقة، وبكل خطوة تمشيها إلى الصلاة صدقة، وتميط الأذى عن الطريق صدقة»" where id = '9a483832-b4ef-4e89-a30b-b93486aa91b0';
update public.questions set source_quote = "«إن أحدكم يجمع خلقه في بطن أمه أربعين يوما نطفة، ثم يكون علقة مثل ذلك، ثم يكون مضغة مثل ذلك»" where id = 'e62798c1-f97f-4ca7-926e-f3ab931b6b80';
update public.questions set source_quote = "«إن الشرك لظلم عظيم»" where id = '80bc1390-88d3-4749-b6f5-8ec7faf53c88';
update public.questions set source_quote = "«بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمدا رسول الله، وإقام الصلاة، وإيتاء الزكاة، والحج، وصوم رمضان»" where id = 'c055e3dc-5298-4f90-9f5a-4994fc90fe94';
